UPDATE draw_order SET award_fulfillment_status = #{awardFulfillmentStatus}, fulfilled_at = now(), update_time = now()
WHERE u_id = #{uId} AND order_id = #{orderId} AND award_id = #{awardId}
  AND award_fulfillment_status != #{awardFulfillmentStatus}


UPDATE draw_order SET stock_settlement_event_status = 4, update_time = now()
WHERE u_id = #{uId} AND order_id = #{orderId}

  AND stock_settlement_event_status IN (0, 2, 3)

mapper.select:
SELECT u_id, order_id, take_id, award_id, award_type, award_name, award_content, grant_type, scheduled_at FROM draw_order WHERE stock_settlement_event_status = 1
AND award_fulfillment_status != 1 AND (fulfillment_event_status = 2 OR (fulfillment_event_status = 0 AND create_time < DATE_SUB(NOW(), INTERVAL 30 MINUTE))
OR (fulfillment_event_status IN (1, 3) AND update_time < DATE_SUB(NOW(), INTERVAL 10 MINUTE))) LIMIT #{limit}

SELECT u_id, order_id, draw_config_id, award_id FROM draw_order
WHERE stock_settlement_event_status IN (0, 2)
OR (stock_settlement_event_status = 3 AND update_time < DATE_SUB(NOW(), INTERVAL 10 MINUTE)) ORDER BY create_time ASC LIMIT #{limit}
